-- ============================================================================
-- Local ICD-11 code bundle
-- ============================================================================
-- The live WHO ICD-11 API (see the now-unused search-icd11.ts history)
-- needs external network access and API credentials that turned out to
-- be more friction than they're worth for a single-clinic app. This
-- table is a curated, offline bundle instead: ~377 common diagnoses
-- (mental/behavioural disorders across the major ICD-11 categories, plus
-- the general-medicine conditions already tracked in the patient HISTORY
-- template — seizure disorder, sickle cell disease, asthma, hypertension,
-- diabetes, tuberculosis, head injury, etc.) fetched once via the WHO API
-- and stored here as plain reference data.
--
-- This is NOT the full ~17,000-entry ICD-11 MMS classification — it's a
-- practical subset for this practice's actual caseload. Free-text
-- diagnosis entry remains available in the UI for anything not covered
-- here. To add more codes later, search https://icd.who.int/browse11 and
-- insert additional (code, title, uri) rows.
-- ============================================================================

create table if not exists public.icd11_codes (
  code  text primary key,
  title text not null,
  uri   text not null
);

create index if not exists icd11_codes_title_idx on public.icd11_codes (lower(title));

alter table public.icd11_codes enable row level security;

revoke all on public.icd11_codes from anon;
grant select on public.icd11_codes to authenticated;

drop policy if exists "icd11_codes_admin_select" on public.icd11_codes;
create policy "icd11_codes_admin_select" on public.icd11_codes
  for select using (public.is_admin());

on conflict (code) do update set title = excluded.title, uri = excluded.uri;